export const MESSAGES: Record<string, Dict> = { zh, en, ja, ko, es };

// —— 非 React 场景取词（数据模块里的纯函数：错误文案、倒计时、规则串）——
// SiteProvider 把自己的 tf 注入进来，链路与组件里的 t() 完全一致（后台 ui_strings → 当前语言 → zh → 兜底）。
// 未注入时（首屏之前、后台页、单测）原样返回中文兜底，行为等同于注入前的旧代码。
type TextResolver = (key: string, vars: Record<string, string | number>, fallback: string) => string;
let resolver: TextResolver = (_key, _vars, fallback) => fallback;

export function setTextResolver(next: TextResolver | null): void {
  resolver = next ?? ((_k, _v, fb) => fb);
}

export function text(key: string, fallback: string, vars: Record<string, string | number> = {}): string {
  return resolver(key, vars, fallback);
}
